import * as T from 'three';import{block,VoxelAssetFactory}from'../builders/VoxelAssetFactory.js';import{MapPropBuilder}from'../builders/MapPropBuilder.js';export function build(g){const root=new T.Group(),b=new MapPropBuilder(root);b.platform(0,-.3,0,100,100);b.platform(0,-.25,0,8,60,0xf5e8ba);b.decorate();b.machine(10,0,'🥚 25 🪙');b.pad(10,3,'🥚 25',0xfba1d3,()=>g.incubator.hatch());b.machine(18,0,'👑 🥚');b.pad(18,3,'👑 🥚',0xffd457,()=>g.incubator.hatch(true));b.machine(-10,-12,'🐾 + 🐾');b.pad(-10,-8,'🧬 10',0xb6a0ff,()=>g.merge.merge());b.machine(-18,-12,'🐾 + ❄️');b.pad(-18,-8,'❄️ 40',0x85ecf6,()=>g.merge.merge(true));b.pad(-5,0,'⚡ Melhorar',0xffdc66,()=>g.treadmill.upgrade());b.pad(12,13,'🏡 Melhorar',0xa6f08e,()=>g.sanctuary.upgrade());block(root,0x466485,-10,.35,0,3,.7,6);for(let i=0;i<12;i++)block(root,i%2?0x3e4c68:0x8eabc1,-10,.75,-2.7+i*.48,2.6,.1,.24);for(const x of [-11.8,-8.2]){block(root,0xbadcf1,x,1.2,0,.15,1.5,5);block(root,0x78ece3,x,2,0,.2,.15,5)}g.boss.bosses=[];['Rei Slime','Golem','Mecha Dino','Dragão'].forEach((name,i)=>{const x=(i%2?1:-1)*30,z=i<2?-25:25;b.platform(x,-.2,z,17,17,[0xb3a2ed,0xf5ce9e][i%2]);const mesh=VoxelAssetFactory.pet(i+1,true);mesh.scale.setScalar(3+i*.2);mesh.position.set(x,0,z);root.add(mesh);const ring=new T.Mesh(new T.RingGeometry(3.8,4,48),new T.MeshBasicMaterial({color:0xef7d89,side:T.DoubleSide,transparent:true,opacity:.65}));ring.rotation.x=-Math.PI/2;ring.position.set(x,.03,z);root.add(ring);g.boss.bosses.push({id:i,name,x,z,mesh,ring,max:80+i*80,hp:80+i*80,dead:0})});g.habitatRoot=new T.Group();g.habitatRoot.position.set(13,0,17);root.add(g.habitatRoot);return{root,b,spawn:new T.Vector3(0,0,10)}}
